SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsChangePasswordRequest
{
    DataAreaId dataAreaId;
    str        userName;
    str        currentPassword;
    str        newPassword;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
}

/// <summary>
/// Required even for a forced change. Without it, anyone who picks up an unlocked handheld
/// mid-shift can lock the worker out of their own account.
/// </summary>
[DataMemberAttribute('CurrentPassword')]
public str parmCurrentPassword(str _value = currentPassword)
{
    currentPassword = _value;
    return currentPassword;
}

[DataMemberAttribute('NewPassword')]
public str parmNewPassword(str _value = newPassword)
{
    newPassword = _value;
    return newPassword;
}
